import pandas as pd

def clean(df):
    df = df.copy()
    df = df.drop_duplicates().copy()

    for col in ['species', 'island']:
        if col in df.columns:
            df[col] = df[col].astype('string').str.strip()

    if 'sex' in df.columns:
        s = df['sex'].astype('string').str.strip().str.lower()
        df['sex'] = s.where(s.isin(['male', 'female']), pd.NA)

    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = pd.to_numeric(
            df['body_mass_g'].astype(str).str.replace(',', '', regex=False),
            errors='coerce'
        )

    if 'flipper_length_mm' in df.columns:
        fl = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
        fl = fl.abs()
        fl = fl.where(fl.between(170, 235), pd.NA)
        df['flipper_length_mm'] = fl

    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['species', 'flipper_length_mm'])
    result = d.groupby('species')['flipper_length_mm'].mean()
    return {str(k): float(v) for k, v in result.items()}
